return Array.from(document.querySelectorAll('.mntl-recipe-card-meta')).slice(0, 6).map(el => {
  const title = el.closest('a')?.getAttribute('href');
  const name = el.parentElement?.querySelector('span')?.innerText || '';
  return { name, html: el.innerHTML.substring(0, 500) };
});

return Array.from(document.querySelectorAll('[id^="mntl-recipe-star-rating_"]')).slice(0, 8).map(el => {
  return {
    title: el.closest('a')?.querySelector('span span, .card__title')?.innerText || '',
    href: el.closest('a')?.getAttribute('href'),
    ratingText: el.parentElement?.innerText || '',
    ratingContainerText: el.innerText
  };
});

return Array.from(document.querySelectorAll('[id^="mntl-recipe-card-meta_"]')).map(meta => {
  const title = meta.parentElement.parentElement.querySelector('span span')?.innerText || '';
  const stars = meta.querySelectorAll('svg');
  const filledStars = Array.from(stars).map(s => {
    const path = s.querySelector('path');
    const d = path?.getAttribute('d') || '';
    return { d: d.substring(0, 30), ariaLabel: s.getAttribute('aria-label') };
  });
  return { title, filledStars };
});

return Array.from(document.querySelectorAll('[id^="mntl-recipe-star-rating_"]')).map(svg => {
  const inner = svg.innerHTML.substring(0, 2000);
  const rects = svg.querySelectorAll('rect');
  return { 
    id: svg.id,
    svgContent: inner, 
    rectCount: rects.length,
    rectFills: Array.from(rects).map(r => r.getAttribute('fill')).slice(0, 3),
    ratingStyle: svg.querySelector('[style*="width"]')?.getAttribute('style')
  };
});

const ingredients = Array.from(document.querySelectorAll('[id^="mntl-structured_ingredients_"] li, .mntl-structured-ingredients li, .recipe-ingredient')).map(li => li.innerText.trim());
return { 
  full: ingredients.join('\n'),
  hasZucchini: ingredients.some(i => i.toLowerCase().includes('zucchini'))
};

const items = document.querySelectorAll('li[class*="ingredient"], li[data-ingredient], .mm-recipes-structured-ingredients li');
const result = Array.from(items).map(i => i.innerText.trim()).filter(Boolean);
return { 
  count: result.length, 
  full: result.join('\n'),
  hasZucchini: result.some(i => i.toLowerCase().includes('zucchini'))
};

const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  const titleEl = card.querySelector('.mntl-recipe-card-meta__title, [class*="recipe-card__title"]');
  const title = titleEl ? titleEl.textContent.trim() : '';
  const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');
  let rating = '';
  let reviewCount = '';
  if (ratingContainer) {
    rating = ratingContainer.getAttribute('data-rating') || ratingContainer.getAttribute('aria-label') || '';
    const countEl = ratingContainer.parentElement.querySelector('.mntl-recipe-card-meta__rating-count-number, [class*="rating-count"]');
    // Find sibling div with rating number
    const parent = ratingContainer.parentElement;
    const divs = parent.querySelectorAll('div');
    for (const d of divs) {
      const t = d.textContent.trim();
      if (/^\d+(\.\d+)?$/.test(t)) {
        reviewCount = t;
        break;
      }
    }
  }
  if (!rating) {
    // Try to get from stars via aria-label or fill amount
    const stars = card.querySelectorAll('[id^="mntl-recipe-star-rating"] svg');
    if (stars.length > 0) {
      const fillPercent = Array.from(stars).map(s => {
        const style = s.getAttribute('style') || '';
        const match = style.match(/--rating:([\d.]+)/);
        if (match) return parseFloat(match[1]);
        const fill = s.getAttribute('fill') || '';
        return fill;
      });
      rating = fillPercent.join(',');
    }
  }
  results.push({ title, rating, reviewCount, url: card.href });
}
return results;

const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  // Get title
  const titleEl = card.querySelector('.mntl-recipe-card-meta__title');
  const title = titleEl ? titleEl.textContent.trim() : '';

  // Get rating container and find the actual rating value via aria-label or inner text
  const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');
  let rating = '';
  if (ratingContainer) {
    rating = ratingContainer.getAttribute('data-rating') || 
             ratingContainer.getAttribute('aria-label') || 
             ratingContainer.getAttribute('title') || '';
    if (!rating) {
      // Look at the SVG stars for fill information
      const stars = ratingContainer.querySelectorAll('svg');
      const ratings = Array.from(stars).map(s => {
        return s.getAttribute('data-rating') || s.getAttribute('aria-label') || s.outerHTML.substring(0,200);
      });
      rating = 'stars:' + ratings.join('|');
    }
  }

  // Get review count - find the next div sibling
  let reviewCount = '';
  if (ratingContainer) {
    const parent = ratingContainer.parentElement;
    const divs = parent.querySelectorAll('div');
    for (const d of divs) {
      if (d === ratingContainer) continue;
      const t = d.textContent.trim();
      if (/^\d+/.test(t)) {
        reviewCount = t;
        break;
      }
    }
  }

  results.push({ title, rating, reviewCount, url: card.href });
}
return results;

const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  const titleEl = card.querySelector('.mntl-recipe-card-meta__title');
  const title = titleEl ? titleEl.textContent.trim() : '';
  const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');

  let ratingText = '';
  if (ratingContainer) {
    const fillEls = ratingContainer.querySelectorAll('[style*="--rating"]');
    const ratings = [];
    for (const f of fillEls) {
      const style = f.getAttribute('style') || '';
      const m = style.match(/--rating:\s*([\d.]+)/);
      if (m) ratings.push(parseFloat(m[1]));
    }
    if (ratings.length > 0) {
      const total = ratings.reduce((a,b) => a+b, 0);
      ratingText = total.toFixed(2);
    } else {
      ratingText = ratingContainer.getAttribute('aria-label') || ratingContainer.getAttribute('data-rating') || '';
    }
  }

  let reviewCount = '';
  if (ratingContainer) {
    const parent = ratingContainer.parentElement;
    const divs = parent.querySelectorAll('div');
    for (const d of divs) {
      if (d === ratingContainer) continue;
      const t = d.textContent.trim();
      if (/^\d+(\.\d+)?$/.test(t)) {
        reviewCount = t;
        break;
      }
    }
  }

  results.push({ title, rating: ratingText, reviewCount, url: card.href });
}
return JSON.stringify(results, null, 2);

