function extract() {
  const name = document.querySelector('h1')?.textContent?.trim() || 'Unknown';
  const prepTime = document.body.textContent.match(/Prep Time:\s*(\d+\s*mins?)/)?.[1] || 'Unknown';
  const cookTime = document.body.textContent.match(/Cook Time:\s*(\d+\s*\w*)/)?.[1] || 'Unknown';
  const totalTime = document.body.textContent.match(/Total Time:\s*(\d+\s*\w*)/)?.[1] || 'Unknown';
  const servings = document.body.textContent.match(/Servings:\s*(\d+)/)?.[1] || 'Unknown';
  const ingredients = Array.from(document.querySelectorAll('[data-ingredient-name], .mntl-structured-ingredients__list-item, .recipe-ingredients__list-item, li[class*="ingredient"]')).slice(0, 10).map(el => el.textContent.trim().substring(0, 100));
  const url = window.location.href;
  return { name, prepTime, cookTime, totalTime, servings, ingredients, url };
}
return extract();

() => {
  // Find reviews section and any sorting controls
  const reviewSection = document.querySelector('#reviews, [id*="review"], .reviews, [class*="review"]');
  const sortControls = document.querySelectorAll('[class*="sort"], [aria-label*="sort"], select');
  const tabs = document.querySelectorAll('[role="tab"], button[class*="tab"]');

  // Find all review elements
  const reviews = [];
  document.querySelectorAll('[class*="review"], [data-test*="review"]').forEach((el, i) => {
    if (i < 20) {
      const text = el.innerText.substring(0, 500);
      reviews.push(text);
    }
  });

  // Find the reviews header and sort options
  const headers = [];
  document.querySelectorAll('h2, h3, [class*="title"]').forEach((el, i) => {
    const text = el.innerText;
    if (text && (text.toLowerCase().includes('review') || text.toLowerCase().includes('rating'))) {
      headers.push(text);
    }
  });

  return {
    reviewSectionFound: !!reviewSection,
    sortControls: Array.from(sortControls).map(c => ({tag: c.tagName, text: c.innerText, ariaLabel: c.getAttribute('aria-label'), id: c.id, className: c.className})),
    tabs: Array.from(tabs).map(t => ({text: t.innerText, ariaLabel: t.getAttribute('aria-label')})),
    headers: headers,
    sampleReviews: reviews.slice(0, 5)
  };
}

() => {
  // Look for review sort options
  const reviewSort = [];
  document.querySelectorAll('button, a, select, [role="button"], [role="tab"]').forEach((el) => {
    const text = el.innerText.trim();
    if (text && (text.toLowerCase().includes('recent') || text.toLowerCase().includes('helpful') || text.toLowerCase().includes('newest') || text.toLowerCase().includes('oldest'))) {
      const ariaLabel = el.getAttribute('aria-label');
      const id = el.id;
      reviewSort.push({tag: el.tagName, text: text, ariaLabel: ariaLabel, id: id, className: el.className});
    }
  });

  // Find the review container
  const reviewContainer = document.querySelector('#reviews, [id*="review"], .reviews-section');

  return {
    sortOptions: reviewSort,
    reviewContainerExists: !!reviewContainer,
    bodyHtml: document.body.innerText.substring(0, 500)
  };
}

() => {
  // Look for review sort options
  const sortButtons = [];
  document.querySelectorAll('button, a, [role="button"], [role="tab"]').forEach((el) => {
    const text = (el.innerText || '').trim();
    const lc = text.toLowerCase();
    if (text && (lc.includes('recent') || lc.includes('helpful') || lc.includes('newest') || lc.includes('oldest') || lc.includes('sort'))) {
      sortButtons.push({tag: el.tagName, text: text.substring(0, 100), ariaLabel: el.getAttribute('aria-label'), id: el.id, dataTest: el.getAttribute('data-test')});
    }
  });

  return { sortButtons: sortButtons.slice(0, 20) };
}

